-- migrate:up
-- Every Lab Member query still fails with HTTP 400 `"_some" can only be used with top level relational
-- alias field` after hotfix 20261009000142 (found 2026-10-10 building feat/record-codes; reproduced on a
-- restored copy of live: 20 of the 36 collections a Lab Member can read return 400, including
-- equipment, materials and fast_recipes, whose own rules have no `_some`).
--
-- Directus 11.17 (api: database/run-ast/lib/apply-query/filter) handles `_some` only directly under an
-- O2M field at the top of a filter, or at the top of the subquery that another legal `_some` opens.
-- Anywhere else it throws. Hotfix 142 kept the OUTERMOST `_some` of each path, but that one is often
-- still behind a to-one hop, e.g. `sample_id.co_owners._some.user_id` in manufacturing_operations.read,
-- and 142 changed read rows only, so update/delete rows kept theirs too. A legal `_some` subquery also
-- applies the related collection's own permission rows (getCases), so one illegal row breaks every
-- collection whose rule reaches it: this is why a top-level `co_owners._some` on physical_samples
-- still 400s (sample_co_owners' own rule is illegal).
--
-- scripts/gen_access_rules.py's path_filter() now keeps a `_some` only where Directus accepts it and
-- drops the rest; a bare to-many hop in a permission filter still means "any row". Checked on a
-- restored copy of live (2026-10-10) for three Lab Members (the real one, one switched to Lab Member
-- in the copy, and a fixture user reaching records only through co-ownership, a secondary
-- investigator seat and a campaign): every ruled collection returns 200 with exactly the rows a
-- plain-SQL evaluation of the same rules gives, no duplicates, and paging and filter_count agree;
-- owned updates 200, foreign updates and deletes 403, sample and operation creates 200.
--
-- The rows below are `python3 scripts/gen_access_rules.py --values` (a snapshot of the rules on
-- 2026-10-10, as in 20261007000141). Only `permissions` is set, and only on Lab Member rows whose
-- filter differs: on live that is 36 rows (17 read, 11 update, 8 delete). validation, fields, rows of
-- other collections and other policies, and missing rows are not touched. What it overwrites is
-- kept in d1_private.lab_member_some_fix_backup for `down`.
--
-- Directus caches permissions: flush Redis and restart Directus after applying.

CREATE SCHEMA IF NOT EXISTS d1_private;

CREATE TABLE d1_private.lab_member_some_fix_backup AS
    SELECT id, permissions FROM directus_permissions WITH NO DATA;
ALTER TABLE d1_private.lab_member_some_fix_backup ADD PRIMARY KEY (id);
COMMENT ON TABLE d1_private.lab_member_some_fix_backup IS
    'Migration 20261010000160: the Lab Member permission filters it replaced (directus_permissions.id, old permissions). `migrate:down` restores them and drops the table.';

