backup AS (
    INSERT INTO d1_private.lab_member_some_fix_backup (id, permissions)
    SELECT p.id, p.permissions
      FROM directus_permissions p
      JOIN generated g ON g.collection = p.collection AND g.action = p.action
     WHERE p.policy = '20000002-0000-0000-0000-000000000002'
       AND coalesce(p.permissions::jsonb, '{}'::jsonb) IS DISTINCT FROM g.filter::jsonb
    RETURNING id
)
UPDATE directus_permissions p
   SET permissions = g.filter::json
  FROM backup b, generated g
 WHERE b.id = p.id AND g.collection = p.collection AND g.action = p.action;

